<script setup>
import { computed, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppShell from '@/components/shell/AppShell.vue'
import MathFieldInput from '@/components/common/MathFieldInput.vue'
import { renderMarkdown } from '@/utils/markdown'
import { usePracticeStore } from '@/stores/practiceStore'
const route=useRoute(), router=useRouter(), store=usePracticeStore()
const q=computed(()=>store.currentQuestion), feedback=computed(()=>q.value&&store.feedback[q.value.question_id])
const hintVisible=computed(()=>q.value&&store.showHint[q.value.question_id])
const hintText=computed(()=>Array.isArray(q.value?.common_mistakes)?q.value.common_mistakes.filter(Boolean).join('；'):q.value?.common_mistakes)
const answeredCount=computed(()=>Object.keys(store.feedback).length)
const pendingCount=computed(()=>(store.session?.questions?.length||0)-answeredCount.value)
const behaviorLabel=computed(()=>({immediate:'即时反馈',adaptive:'自适应练习',deferred:'统一反馈'}[store.behavior]||'即时反馈'))
const canRetryNow=computed(()=>q.value?store.canRetry(q.value.question_id):false)
const stateOf=(item)=>{const fb=store.feedback[item.question_id];return fb?(fb.feedback_deferred?'submitted':fb.correct?'correct':'wrong'):''}
let snapshotTimer=null
const persistSnapshot=()=>{store.saveSnapshot()}
onMounted(async()=>{await store.loadSession(route.params.sessionId); if(store.session.status==='created') await store.start(); snapshotTimer=setInterval(persistSnapshot,30000); globalThis.addEventListener?.('pagehide',persistSnapshot)})
onUnmounted(()=>{if(snapshotTimer)clearInterval(snapshotTimer); globalThis.removeEventListener?.('pagehide',persistSnapshot)})
async function submit(){await store.submitCurrent()}
function toggleMulti(questionId, optionId){
  const current=Array.isArray(store.answers[questionId])?store.answers[questionId]:[]
  const next=current.includes(optionId)?current.filter((id)=>id!==optionId):[...current,optionId]
  store.answers[questionId]=next
}
async function finish(){
  if(pendingCount.value&&!globalThis.confirm(`还有 ${pendingCount.value} 题未提交，未提交的题目将按未作答计入结果。确定结束练习吗？`))return
  await store.complete();router.push(`/apply/practice/sessions/${route.params.sessionId}/result`)
}
</script>
<template><AppShell><template #topbar-title>专项练习 · {{store.currentIndex+1}}/{{store.session?.questions?.length||0}}</template><main v-if="q" class="runner"><header><span class="behavior-badge">{{behaviorLabel}}</span><span>已提交 {{answeredCount}} 题<template v-if="pendingCount"> · 待提交 {{pendingCount}} 题</template></span></header><p v-if="store.error" role="alert" class="error">{{store.error}}</p><section class="question"><div class="meta">第 {{q.position}} 题 · {{q.question_type}}</div><div class="math" v-html="renderMarkdown(q.content)"/><div v-if="q.question_type==='choice'" class="options"><label v-for="o in q.options||[]" :key="o.id"><input v-model="store.answers[q.question_id]" type="radio" :value="o.id" :disabled="!!feedback">{{o.id}}. <span v-html="renderMarkdown(o.text)"/></label></div><div v-else-if="q.question_type==='multi_choice'" class="options"><span class="multi-hint">多选题：勾选所有正确选项后提交</span><label v-for="o in q.options||[]" :key="o.id"><input :checked="(store.answers[q.question_id]||[]).includes(o.id)" type="checkbox" :value="o.id" :disabled="!!feedback" @change="toggleMulti(q.question_id,o.id)">{{o.id}}. <span v-html="renderMarkdown(o.text)"/></label></div><div v-else-if="q.question_type==='judge'" class="options"><label><input v-model="store.answers[q.question_id]" type="radio" value="true" :disabled="!!feedback">对</label><label><input v-model="store.answers[q.question_id]" type="radio" value="false" :disabled="!!feedback">错</label></div><MathFieldInput v-else v-model="store.answers[q.question_id]" :numeric="q.question_type==='numeric_fill'" :disabled="!!feedback" :placeholder="q.question_type==='numeric_fill'?'输入数值答案（可点公式键盘）':'输入表达式，例如 x^2+1'"/><div v-if="!feedback&&hintText" class="hint"><button type="button" class="hint-toggle" :aria-expanded="hintVisible?'true':'false'" @click="store.revealHint(q.question_id)">{{hintVisible?'提示':'看提示（不计入对错，仅记录学习信号）'}}</button><p v-if="hintVisible" class="hint-text">💡 {{hintText}}</p></div></section><section v-if="feedback" class="feedback" :class="feedback.feedback_deferred?'deferred':feedback.correct?'correct':'incorrect'"><template v-if="feedback.feedback_deferred"><strong>已提交</strong><p>统一反馈练习：完成全部题目后，在结果页查看每题对错与解析。</p></template><template v-else><strong>{{feedback.correct?'回答正确':'回答有误'}}</strong><p>正确答案：{{feedback.correct_answer}}</p><div v-if="feedback.analysis" class="math" v-html="renderMarkdown(feedback.analysis)"/><div v-if="canRetryNow" class="retry-row"><button type="button" class="retry" @click="store.beginRetry(q.question_id)">{{store.behavior==='adaptive'?`再试一次（第 ${feedback.retry_count+2} 次作答）`:'重试一次'}}</button><span class="retry-note">重试会记录两次作答，判分以最新一次为准</span></div></template></section><nav aria-label="题目导航"><button :disabled="store.currentIndex===0" @click="store.currentIndex--">上一题</button><div class="numbers"><button v-for="(item,index) in store.session.questions" :key="item.question_id" :class="{active:index===store.currentIndex,[stateOf(item)]:true}" :aria-label="`第 ${index+1} 题`" :aria-current="index===store.currentIndex?'step':undefined" @click="store.currentIndex=index">{{index+1}}</button></div><button v-if="store.currentIndex<store.session.questions.length-1" class="primary" :disabled="store.loading" @click="store.currentIndex++">下一题</button><button v-else class="primary" :disabled="store.loading" @click="finish">完成练习</button></nav><footer class="submit-row"><button v-if="!feedback" class="primary" :disabled="store.loading || store.answers[q.question_id]===undefined || store.answers[q.question_id]===''" @click="submit">提交本题</button></footer></main><p v-else class="loading">正在恢复练习…</p></AppShell></template>
<style scoped>.runner{max-width:920px;margin:0 auto;padding:28px 24px 88px}.runner>header{display:flex;justify-content:space-between;align-items:center;color:var(--text-secondary);font-size:14px}.behavior-badge{display:inline-flex;align-items:center;min-height:26px;padding:0 10px;border-radius:var(--radius-sm);background:var(--accent-soft);color:var(--text-primary);font-size:13px;font-weight:600}.question,.feedback{margin-top:18px;padding:24px;border:1px solid var(--border-subtle);border-radius:var(--radius-lg);background:var(--surface)}.meta{color:var(--text-tertiary);font-size:14px;margin-bottom:14px}.math{line-height:1.75}.options{display:flex;flex-direction:column;gap:12px;margin-top:18px}.options label{min-height:36px}.multi-hint{color:var(--text-tertiary);font-size:13px}input:not([type=radio]):not([type=button]){box-sizing:border-box;width:100%;min-height:42px;margin-top:18px;padding:8px;border:1px solid var(--border-subtle);border-radius:var(--radius-sm);font:inherit}.hint{margin-top:16px;border-top:1px dashed var(--border-subtle);padding-top:14px}.hint-toggle{min-height:36px;padding:0 14px;border:1px solid var(--border-subtle);border-radius:var(--radius-sm);background:var(--surface-muted);color:var(--text-secondary);font-size:13px;cursor:pointer}.hint-toggle:hover,.hint-toggle:focus-visible{color:var(--accent);outline:2px solid var(--accent);outline-offset:2px}.hint-text{margin:10px 0 0;padding:10px 12px;border-radius:var(--radius-sm);background:var(--accent-soft);color:var(--text-primary);font-size:14px}.feedback.correct{border-left:4px solid var(--success)}.feedback.incorrect{border-left:4px solid var(--danger)}.feedback.deferred{border-left:4px solid var(--accent)}.retry-row{display:flex;align-items:center;justify-content:flex-end;gap:12px;margin-top:16px;flex-wrap:wrap}.retry{min-height:40px;padding:0 16px;border:1px solid var(--accent);border-radius:var(--radius-sm);background:var(--surface);color:var(--accent);font:inherit;cursor:pointer;transition:background .15s ease,color .15s ease}.retry:hover,.retry:focus-visible{background:var(--accent);color:#fff;outline:2px solid var(--accent);outline-offset:2px}.retry-note{color:var(--text-tertiary);font-size:13px}nav{display:flex;align-items:center;gap:12px;margin-top:24px}.numbers{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;flex:1}.numbers button{min-width:40px;min-height:36px;padding:0;border:1px solid var(--border-subtle);border-radius:var(--radius-sm);background:var(--surface);cursor:pointer;transition:background .2s ease,border-color .2s ease}.numbers button.correct{background:var(--success);border-color:var(--success);color:#fff}.numbers button.wrong{background:var(--danger);border-color:var(--danger);color:#fff}.numbers button.submitted{background:var(--accent-soft);border-color:var(--accent);color:var(--text-primary)}.numbers button.active{outline:2px solid var(--accent);outline-offset:2px}.submit-row{display:flex;justify-content:flex-end;margin-top:16px}button{min-height:44px;padding:0 18px;border:1px solid var(--border-subtle);border-radius:var(--radius-sm);background:var(--surface);color:var(--text-primary);font:inherit;cursor:pointer}.primary{background:var(--accent);border-color:var(--accent);color:#fff}.error{color:var(--danger)}.loading{padding:32px}@media(max-width:600px){.runner{padding:20px 16px 80px}.question,.feedback{padding:18px}nav{flex-wrap:wrap}.numbers{order:3;flex-basis:100%}.retry-row{justify-content:flex-start}}</style>
